function storedLang() {
  try {
    const code = localStorage.getItem(LANG_KEY);
    return LANGS.some(lang => lang.code === code) ? code : null;
  } catch {
    return null;
  }
}

// Idioma del navegador si aún no se ha elegido ninguno.
function browserLang() {
  for (const tag of navigator.languages || [navigator.language || ""]) {
    const code = String(tag).toLowerCase().split("-")[0];
    if (LANGS.some(lang => lang.code === code)) return code;
  }
  return "es";
}

let currentLang = storedLang() || browserLang();

function setLang(code) {
  if (!LANGS.some(lang => lang.code === code)) return;
  currentLang = code;
  try {
    localStorage.setItem(LANG_KEY, code);
  } catch {}
  applyI18n();
}

function t(key, params = {}) {
  const entry = M[key];
  const index = LANGS.findIndex(lang => lang.code === currentLang);
  const text = entry ? (entry[index] ?? entry[0]) : key;
  return text.replace(/\{(\w+)\}/g, (match, name) => (name in params ? String(params[name]) : match));
}

// Traduce los elementos marcados en el HTML:
//   data-i18n="clave"            → textContent
//   data-i18n-html="clave"       → innerHTML (solo textos propios de la extensión)
//   data-i18n-attr="attr:clave;…" → atributos (title, aria-label…)
function applyI18n(root = document) {
  document.documentElement.lang = currentLang;
  root.querySelectorAll("[data-i18n]").forEach(element => {
    element.textContent = t(element.dataset.i18n);
  });
  root.querySelectorAll("[data-i18n-html]").forEach(element => {
    element.innerHTML = t(element.dataset.i18nHtml);
  });
  root.querySelectorAll("[data-i18n-attr]").forEach(element => {
    for (const pair of element.dataset.i18nAttr.split(";")) {
      const [attribute, key] = pair.split(":").map(part => part.trim());
      if (attribute && key) element.setAttribute(attribute, t(key));
    }
  });
  document.dispatchEvent(new CustomEvent("fps-langchange", { detail: currentLang }));
}

// Los scripts van al final del <body>: el HTML ya está cargado y se traduce
// antes de que el script de cada página escriba sus propios textos.
applyI18n();
